suppressPackageStartupMessages({library(data.table);library(ggplot2);library(pROC);library(patchwork)})
d<-'results';mods<-c('DT','GBM','GLM','KNN','LASSO','NNET','RF','SVM');pal<-c(DT='#0072B2',GBM='#E69F00',GLM='#009E73',KNN='#CC79A7',LASSO='#56B4E9',NNET='#D55E00',RF='#F0E442',SVM='#000000')
p<-fread(file.path(d,'outer_test_predictions.csv'));p$model<-factor(p$model,levels=mods);imp<-fread(file.path(d,'outer_test_permutation_importance.csv'));sel<-fread(file.path(d,'outer_training_gene_selection.csv'));freq<-fread(file.path(d,'candidate_selection_frequency.csv'));pooled<-fread(file.path(d,'pooled_auc_ci_metrics.csv'))
im<-imp[,.(mean_auc_drop=mean(auc_drop)),by=.(model,gene)];im[,norm:=pmax(mean_auc_drop,0)/max(pmax(mean_auc_drop,0)),by=model];topg<-im[,.(score=max(norm)),by=gene][order(-score,gene)][1:min(20,.N),gene];ha<-im[gene%in%topg];ha$gene<-factor(ha$gene,levels=rev(topg));ha$model<-factor(ha$model,levels=mods)
pA<-ggplot(ha,aes(model,gene,fill=norm))+geom_tile(color='white',linewidth=.25)+scale_fill_viridis_c(option='D',limits=c(0,1),name='Normalized\nAUC drop')+labs(title='A',subtitle='Post-hoc permutation importance on outer-test samples',x=NULL,y=NULL)+theme_minimal(base_size=10)+theme(panel.grid=element_blank(),plot.title=element_text(face='bold'))
rdf<-fread(file.path(d,'outer_test_residuals.csv'));rdf$model<-factor(rdf$model,levels=mods);pB<-ggplot(rdf,aes(model,residual,color=model,fill=model))+geom_violin(alpha=.14,trim=FALSE)+geom_boxplot(width=.17,outlier.shape=NA,alpha=.3)+scale_color_manual(values=pal)+scale_fill_manual(values=pal)+labs(title='B',subtitle='Absolute probability residuals on outer-test samples',x=NULL,y='|Observed − predicted probability|')+theme_classic(base_size=10)+theme(legend.position='none',plot.title=element_text(face='bold'),axis.text.x=element_text(angle=40,hjust=1))
rocdf<-rbindlist(lapply(mods,function(m){z<-p[model==m];ro<-roc(z$y,z$prob,quiet=TRUE,direction='<');data.table(model=m,FPR=1-ro$specificities,TPR=ro$sensitivities)}));rocdf$model<-factor(rocdf$model,levels=mods);roc_labels<-sprintf('%s (AUC=%.3f)',mods,pooled$pooled_AUC);pC<-ggplot(rocdf,aes(FPR,TPR,color=model))+geom_line(linewidth=.8)+geom_abline(linetype=2,color='grey70')+scale_color_manual(values=pal,labels=roc_labels,name='Pooled OOF ROC')+coord_equal()+labs(title='C',subtitle='Pooled outer-test predictions; AUC is not mean fold AUC',x='1 − specificity',y='Sensitivity')+theme_classic(base_size=10)+theme(plot.title=element_text(face='bold'),legend.position='right')
freq<-freq[order(-selection_frequency,gene)];hm<-merge(CJ(gene=freq$gene,outer_fold=1:5),sel[,.(gene,outer_fold,selected=1)],by=c('gene','outer_fold'),all.x=TRUE);hm[is.na(selected),selected:=0];hm$gene<-factor(hm$gene,levels=rev(freq$gene));pD<-ggplot(hm,aes(factor(outer_fold),gene,fill=factor(selected)))+geom_tile(color='white')+scale_fill_manual(values=c('0'='#F1F1F1','1'='#0072B2'),labels=c('Not selected','Selected'),name=NULL)+labs(title='D',subtitle='Outer-training-fold selection; PTGS2 and IL1B selected in 5/5 folds',x='Outer training fold',y=NULL)+theme_minimal(base_size=9)+theme(panel.grid=element_blank(),plot.title=element_text(face='bold'),legend.position='bottom')
fig<-(pA|pB)/(pC|pD)+plot_annotation(title='Exploratory nested cross-validation of 20 preselected hub genes',subtitle='Conditional validation within the Figure 2D candidate universe',theme=theme(plot.title=element_text(face='bold',size=14),plot.subtitle=element_text(size=9)))
ggsave('figures/Figure3_publication.pdf',fig,width=12,height=9,units='in',device=cairo_pdf);ggsave('figures/Figure3_publication.png',fig,width=12,height=9,units='in',dpi=350);ggsave('figures/Figure3_publication.tif',fig,width=12,height=9,units='in',dpi=350,compression='lzw')
